<?php namespace App\Http\Controllers;use App\Models\AssetAssignment;use App\Models\HrAssetCustodyRecord;use Illuminate\Http\Request;class HrAssetCustodyController extends AccountBaseController{public function index(){$this->assignments=AssetAssignment::with('asset')->where('employee_id',user()->id)->whereIn('status',['Pending','Assigned'])->get();$this->records=HrAssetCustodyRecord::where('employee_id',user()->id)->get()->keyBy('asset_assignment_id');return view('hr-asset-custody.index',$this->data);}public function acknowledge(Request $r,AssetAssignment $assignment){abort_403($assignment->employee_id!==user()->id);$d=$r->validate(['condition'=>'required|string|max:255','evidence'=>'nullable|file|max:5120']);$path=$r->file('evidence')?->store('hr-custody','public');HrAssetCustodyRecord::updateOrCreate(['asset_assignment_id'=>$assignment->id],['employee_id'=>user()->id,'accepted_at'=>now(),'received_condition'=>$d['condition'],'evidence_path'=>$path]);return back()->with('success','Asset receipt acknowledged.');}public function return(Request $r,AssetAssignment $assignment){abort_403($assignment->employee_id!==user()->id);$d=$r->validate(['condition'=>'required|string|max:255','notes'=>'nullable|string|max:2000','evidence'=>'nullable|file|max:5120']);$path=$r->file('evidence')?->store('hr-custody','public');HrAssetCustodyRecord::updateOrCreate(['asset_assignment_id'=>$assignment->id],['employee_id'=>user()->id,'returned_at'=>now(),'return_condition'=>$d['condition'],'incident_notes'=>$d['notes']??null,'evidence_path'=>$path]);return back()->with('success','Asset return recorded for HR clearance.');}}
